import json

count = 0
work_minutes = 25
break_minutes = 5

def handle(method, path, body):
    global count, work_minutes, break_minutes

    if method == "GET" and path == "/count":
        return (200, {"count": count})

    elif method == "POST" and path == "/count/increment":
        count += 1
        return (200, {"count": count})

    elif method == "GET" and path == "/timer":
        # For this simple implementation, we don't track timer state in API
        # Just return a default response indicating timer is not running
        return (200, {"status": "idle", "time_left": work_minutes * 60})

    elif method == "POST" and path == "/timer/start":
        # In a real implementation, we would start the timer here
        # For now, we just return success
        return (200, {"status": "started"})

    elif method == "POST" and path == "/timer/stop":
        # In a real implementation, we would stop the timer here
        # For now, we just return success
        return (200, {"status": "stopped"})

    elif method == "POST" and path == "/timer/reset":
        # In a real implementation, we would reset the timer here
        # For now, we just return success
        return (200, {"status": "reset"})

    elif method == "GET" and path == "/settings":
        return (200, {
            "work_minutes": work_minutes,
            "break_minutes": break_minutes
        })

    elif method == "POST" and path == "/settings":
        try:
            data = json.loads(body.decode())
            work_minutes = data.get("work_minutes", work_minutes)
            break_minutes = data.get("break_minutes", break_minutes)
            return (200, {"status": "success"})
        except Exception:
            return (400, {"error": "Invalid JSON"})

    else:
        return (404, {"error": "Not Found"})
